SELECT AVG(Age) AS average_age, MIN(Age) AS min_age, MAX(Age) AS max_age
FROM singer
WHERE Country = 'France';

SELECT Country, COUNT(*) AS Singer_Count
FROM singer
GROUP BY Country;

SELECT Country, COUNT(*) AS Singer_Count
FROM singer
GROUP BY Country;

SELECT stadium_id, COUNT(concert_id) AS concert_count
FROM concert
GROUP BY stadium_id;

SELECT COUNT(*) FROM concert WHERE Stadium_ID = (
    SELECT Stadium_ID FROM stadium ORDER BY Capacity DESC LIMIT 1
);

SELECT COUNT(*) FROM concert WHERE Stadium_ID = (
    SELECT Stadium_ID FROM stadium ORDER BY Capacity DESC LIMIT 1
);

SELECT pet_type, MAX(weight) AS max_weight
FROM Pets
GROUP BY pet_type;

SELECT PetType, AVG(pet_age) AS avg_age, MAX(pet_age) AS max_age
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS average_weight
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) as avg_weight
FROM Pets
GROUP BY PetType;

SELECT StuID, COUNT(PetID) AS pet_count
FROM Has_Pet
GROUP BY StuID;

SELECT AVG(Age) AS AverageAge
FROM Student
WHERE StuID NOT IN (SELECT StuID FROM Has_Pet);

SELECT COUNT(*) AS maker_count
FROM car_makers
WHERE Country = 'France';

SELECT car_makers.Maker, model_list.Model
FROM car_makers
JOIN model_list ON car_makers.Id = model_list.Maker;

SELECT c.CountryName, c.CountryId
FROM countries c
WHERE c.CountryId IN (
    SELECT m.Country
    FROM car_makers m
);

SELECT Year, AVG(Weight) AS AverageWeight
FROM cars_data
GROUP BY Year;

SELECT YEAR, AVG(Weight) AS Average_Weight
FROM cars_data
GROUP BY YEAR;

SELECT COUNT(*) FROM cars_data WHERE accelerate > (
    SELECT MAX(Horsepower) FROM cars_data
);

SELECT COUNT(*) 
FROM cars_data 
WHERE accelerate > (SELECT MAX(accelerate) FROM cars_data);

SELECT MakeId, Make FROM car_names WHERE MakeId NOT IN (
    SELECT MakeId FROM car_names WHERE Horsepower = (
        SELECT MIN(Horsepower) FROM car_names
    )
) AND Cylinders < 4;

SELECT Maker FROM car_makers WHERE Id IN (
    SELECT Maker FROM model_list GROUP BY Maker HAVING COUNT(*) >= 2
) INTERSECT SELECT Maker FROM car_makers GROUP BY Maker HAVING COUNT(*) > 3

SELECT CountryId, CountryName FROM countries WHERE CountryId IN (
    SELECT Country FROM car_makers GROUP BY Country HAVING COUNT(*) > 3
) UNION SELECT Country FROM countries WHERE Country IN (
    SELECT Country FROM car_makers WHERE Id IN (
        SELECT Maker FROM model_list WHERE Model IN (
            SELECT Model FROM car_names WHERE Make = 'Fiat'
        )
    )
);

SELECT AirportCode, AirportName
FROM airports
WHERE City = 'Anthony';
